{
    var result = "";
    foreach(var row in rows)
    {
        foreach(var cell in row.cells)
        {
            if(cell.word.IndexOf(name)>-1 )
            {
                if(type=="table")
                {
                    var rowAfter = rows.Find(a => a.num == row.num+additionalRow);
                    var cellAfter = rowAfter.cells.Find(a => Math.Abs(a.X - cell.X) <= 10);
                    if(cellAfter.word!="")
                    {
                        result = cellAfter.word;
                        if(AddInfo=="en")
                        {
                            result = cellAfter.wordEn;
                        }
                    }
                }
                if(type=="regular")
                {
                    var splitted = cell.word.Split(name);
                    if(splitted.Length>1 && AddInfo == "allAfter")
                    {
                        for(var i=1; i<splitted.Length;i++)
                        {
                            if(result!="" && splitted[i]!=" ")
                            {
                                result += " ";
                            }
                            result += splitted[i];
                        }
                    }
                    else
                    {
                        for (var i = 1; i < splitted.Length; i++)
                        {
                            if (splitted[i]!=AddInfo && result != "" && splitted[i] != " ")
                            {
                                result += " ";
                            }
                            if (splitted[i] != AddInfo)
                            {
                                result += splitted[i];
                            }
                            else
                            {
                                i = splitted.Length;
                            }
                        }
                    }
                }
            }
        }
    }
    return result;
}

